<?php

declare(strict_types=1); namespace App\Service\Configurator;
use App\Dto\Configurator\{ConfiguratorConfiguration,ValidationError,ValidationResult}; use App\Entity\Configurator\{Configurator,ConfiguratorDependency,ConfiguratorField}; use App\Enum\Configurator\{DependencyEffect,DependencyOperator,FieldType};
final class ConfiguratorValidator { /** @param iterable<ConfiguratorDependency> $dependencies */ public function validate(ConfiguratorConfiguration $cfg,Configurator $model,iterable $dependencies=[]):ValidationResult{$errors=[];if(!$model->isEnabled()||$model->getCode()!==$cfg->configuratorCode)$errors[]=new ValidationError(null,'configurator_unavailable','Configurator does not exist or is disabled.');if($cfg->quantity<1)$errors[]=new ValidationError('quantity','invalid_quantity','Quantity must be at least one.');$fields=[];foreach($model->getSections() as $section){foreach($section->getFields() as $field)$fields[$field->getCode()]=[$field,$section->isEnabled()];}foreach($cfg->selections as $code=>$selection){if(!isset($fields[$code])){$errors[]=new ValidationError($code,'unknown_field','Field does not belong to the configurator.');continue;}[$field,$sectionEnabled]=$fields[$code];if(!$sectionEnabled||!$field->isEnabled()){$errors[]=new ValidationError($code,'field_disabled','Field or section is disabled.');continue;}$this->validateSelection($field,$selection,$errors);}foreach($fields as $code=>[$field,$sectionEnabled])if($sectionEnabled&&$field->isEnabled()&&$field->isRequired()&&!$this->hasSelection($cfg,$code))$errors[]=new ValidationError($code,'required','A selection is required.');foreach($dependencies as $dependency)if($dependency->isEnabled()&&$this->matches($dependency,$cfg->selections)){$target=$dependency->getTargetField()?->getCode();if($dependency->getEffect()===DependencyEffect::REQUIRE&&$target!==null&&!$this->hasSelection($cfg,$target))$errors[]=new ValidationError($target,'dependency_required','Field is required by a dependency.');if($dependency->getEffect()===DependencyEffect::FORBID&&$target!==null&&$this->hasSelection($cfg,$target))$errors[]=new ValidationError($target,'dependency_forbidden','Selection is forbidden by a dependency.');}return new ValidationResult($errors);}
 /** @param list<ValidationError> $errors */ private function validateSelection(ConfiguratorField $field,mixed $selection,array &$errors):void{$type=$field->getType();$codes=$type===FieldType::MULTIPLE_CHOICE?(is_array($selection)?$selection:[$selection]):(is_array($selection)?$selection:[$selection]);if($type===FieldType::SINGLE_CHOICE&&is_array($selection)&&count($selection)!==1)$errors[]=new ValidationError($field->getCode(),'single_choice_count','Single choice accepts exactly one value.');if(in_array($type,[FieldType::SINGLE_CHOICE,FieldType::MULTIPLE_CHOICE],true)){foreach($codes as $code){$valid=false;foreach($field->getValues() as $value)if($value->getCode()===$code&&$value->isEnabled())$valid=true;if(!$valid)$errors[]=new ValidationError($field->getCode(),'invalid_value','Value does not belong to the field or is disabled.',['value'=>$code]);}return;}if(in_array($type,[FieldType::INTEGER,FieldType::DECIMAL,FieldType::QUANTITY],true)){if(!is_numeric($selection)){$errors[]=new ValidationError($field->getCode(),'not_numeric','A numeric value is required.');return;}$v=(float)$selection;$min=$field->getMinimumValue();$max=$field->getMaximumValue();$step=$field->getStep();if($min!==null&&$v<(float)$min)$errors[]=new ValidationError($field->getCode(),'below_minimum','Value is below its minimum.');if($max!==null&&$v>(float)$max)$errors[]=new ValidationError($field->getCode(),'above_maximum','Value is above its maximum.');if($step!==null&&$min!==null&&abs(fmod($v-(float)$min,(float)$step))>1e-9)$errors[]=new ValidationError($field->getCode(),'invalid_step','Value does not match the configured step.');}}
 private function hasSelection(ConfiguratorConfiguration $c,string $code):bool{return array_key_exists($code,$c->selections)&&$c->selections[$code]!==null&&$c->selections[$code]!==''&&$c->selections[$code]!==[];} /** @param array<string,mixed> $s */ private function matches(ConfiguratorDependency $d,array $s):bool{$actual=$s[$d->getSourceField()->getCode()]??null;$expected=$d->getExpectedValues();return match($d->getOperator()){DependencyOperator::EQUALS=>in_array($actual,$expected,true),DependencyOperator::NOT_EQUALS=>!in_array($actual,$expected,true),DependencyOperator::IN=>count(array_intersect((array)$actual,$expected))>0,DependencyOperator::NOT_IN=>count(array_intersect((array)$actual,$expected))===0,DependencyOperator::GREATER_THAN=>$actual>$expected[0],DependencyOperator::GREATER_THAN_OR_EQUAL=>$actual>=$expected[0],DependencyOperator::LESS_THAN=>$actual<$expected[0],DependencyOperator::LESS_THAN_OR_EQUAL=>$actual<=$expected[0],DependencyOperator::IS_SELECTED=>$actual!==null&&$actual!==false&&$actual!==[]};}
}
